export const CAMPAIGN_VERSION=1,BUNKER_W=30,BUNKER_H=20;
const keys=['food','water','energy','metal','material','fuel','stone','tools','groundwater','ore'];
const clone=x=>JSON.parse(JSON.stringify(x));
