export const activeBunker=c=>c.bunkers.find(b=>b.id===c.active)||c.bunkers[0];
export function boundedWorld(seed){let s=createWorld(seed);s.bunkerBounds={w:30,h:20};s.activeDistrict=0;s.hub={x:18,y:7};s.projectSites=[];s.expeditions=[];s.surveyedRegions=[];for(let c of s.cells){if(c.x>=30||c.y>=20)Object.assign(c,{type:'rock',building:null,feature:null,seen:false});else{c.deep=false;c.surveyed=true;}}addLargeDeposits(s);classifyDeposits(s);return s;}
export function createCampaign(seed=Date.now()>>>0){let world=boundedWorld(seed);return {campaignVersion:1,unexploredResetV18:true,bunker2CleanupV15:true,bunkers234CleanupV17:true,seed,time:0,active:1,nextId:2,bunkers:[{id:1,name:'Убежище 07',gx:0,gy:0,founded:true,automatic:false,world}],links:[],projects:[],shipments:[],dispatchClock:0,transportFuelUsed:0,log:['Новая цель: построить автономный бункер и основать следующее поселение.']};}
