export function migrateCampaign(old){let c={campaignVersion:1,seed:old.seed,time:old.time,active:1,nextId:1,bunkers:[],links:[],projects:[],shipments:[],dispatchClock:0,transportFuelUsed:0,log:['Город перенесён в отдельные бункеры. Запасы разделены без повторного начисления.']},positions=new Map(),oldToBunker=(x,y)=>positions.get(Math.floor(x/30)+','+Math.floor(y/20));
for(let gy=0;gy<2;gy++)for(let gx=0;gx<Math.ceil(W/30);gx++){let local=old.cells.filter(n=>n.x>=gx*30&&n.x<(gx+1)*30&&n.y>=gy*20&&n.y<(gy+1)*20);if(!local.some(n=>n.type==='open'||n.seen)||!local.length)continue;let world=boundedWorld((old.seed+gx*7919+gy*104729)>>>0);world.resources=blank();world.groundwaterMax=0;world.people=[];world.jobs=[];world.time=old.time;world.metrics=null;world.unlocks=[...old.unlocks];world.tech=old.tech;world.researchPoints=0;world.arrivals=0;world.nextId=old.nextId;world.builderReserve=old.builderReserve;world.metalGiftClaimed=true;world.metalGiftRemaining=0;world.waterGiftClaimed=true;world.waterGiftRemaining=0;for(let n of world.cells)if(n.x<30&&n.y<20){n.type='rock';n.building=null;n.seen=false;}for(let n of local){let copy=clone(n);copy.x-=gx*30;copy.y-=gy*20;copy.deep=false;copy.surveyed=true;world.cells[copy.y*W+copy.x]=copy;}
let open=world.cells.filter(n=>n.x<30&&n.y<20&&n.type==='open');world.hub=open.find(n=>n.x===18&&n.y===7)?{x:18,y:7}:open.length?{x:open[0].x,y:open[0].y}:{x:18,y:7};let b={id:c.nextId++,name:c.bunkers.length?'Бункер '+(c.bunkers.length+1):'Убежище 07',gx,gy,founded:open.some(n=>n.building),automatic:false,world};c.bunkers.push(b);positions.set(gx+','+gy,b);}
if(!c.bunkers.length)return createCampaign(old.seed);
for(let p of old.people){let b=oldToBunker(p.x,p.y)||c.bunkers[0],q=clone(p),ox=b.gx*30,oy=b.gy*20;q.x=Math.max(0,Math.min(29,Math.round(p.x)-ox));q.y=Math.max(0,Math.min(19,Math.round(p.y)-oy));q.path=[];q.target=null;q.job=null;q.task='Ожидание';delete q.expedition;delete q.campaignProject;delete q.routeStart;b.world.people.push(q);b.founded=true;}
for(let j of old.jobs){let b=oldToBunker(j.x,j.y);if(b){let q=clone(j);q.x-=b.gx*30;q.y-=b.gy*20;b.world.jobs.push(q);}}
for(let b of c.bunkers)for(let n of b.world.cells)if(n.preferredOperator!==undefined&&!b.world.people.some(p=>p.id===n.preferredOperator))delete n.preferredOperator;
// Local room buffers are part of each resource share. Distribute the remainder by storage capacity.
let founded=c.bunkers.filter(b=>b.founded),weights=founded.map(b=>capacity(b.world)),weight=weights.reduce((a,b)=>a+b,0);
for(let k of keys){let reserved=c.bunkers.map(b=>b.world.cells.reduce((a,n)=>a+(n.supply?.[k]||0),0)),left=Math.max(0,old.resources[k]-reserved.reduce((a,b)=>a+b,0));for(let i=0;i<c.bunkers.length;i++)c.bunkers[i].world.resources[k]=reserved[i];for(let i=0;i<founded.length;i++)founded[i].world.resources[k]+=left*weights[i]/weight;}
for(let b of c.bunkers){b.world.groundwaterMax=b.world.resources.groundwater+Math.max(0,old.groundwaterMax-old.resources.groundwater)*(b.founded?capacity(b.world):0)/weight;b.world.researchPoints=old.researchPoints*(b.founded?capacity(b.world):0)/weight;}
c.bunkers[0].world.arrivals=old.arrivals;c.bunkers[0].world.metalGiftRemaining=old.metalGiftRemaining||0;c.bunkers[0].world.waterGiftRemaining=old.waterGiftRemaining||0;
for(let n of old.cells){if(n.type!=='open')continue;for(let [dx,dy] of [[1,0],[0,1]]){let other=cell(old,n.x+dx,n.y+dy),a=oldToBunker(n.x,n.y),b=other&&oldToBunker(other.x,other.y);if(other?.type!=='open'||!a||!b||a===b||dy&&n.building!=='stairs'&&other.building!=='stairs'||c.links.some(l=>l.a===a.id&&l.b===b.id||l.a===b.id&&l.b===a.id))continue;let ea={x:n.x-a.gx*30,y:n.y-a.gy*20},eb={x:other.x-b.gx*30,y:other.y-b.gy*20};c.links.push({id:c.nextId++,a:a.id,b:b.id,ea,eb,travel:60});cell(a.world,ea.x,ea.y).tunnelTo=b.id;cell(b.world,eb.x,eb.y).tunnelTo=a.id;}}
c.active=c.bunkers.find(b=>b.world.people.some(p=>p.id===old.people[0]?.id))?.id||c.bunkers[0].id;for(let b of c.bunkers){delete b.world.largeGeologyVersion;addLargeDeposits(b.world);}return c;}
export function serializeCampaign(c){return JSON.stringify(c);}
export function restoreCampaign(text){let raw=JSON.parse(text);if(!raw.campaignVersion)return migrateCampaign(restore(text));if(raw.campaignVersion!==1||!Array.isArray(raw.bunkers)||raw.bunkers.length<1||raw.bunkers.length>12||!Array.isArray(raw.links)||!Array.isArray(raw.projects)||!Array.isArray(raw.shipments)||!Number.isFinite(raw.time)||raw.time<0||!Number.isInteger(raw.nextId)||!Array.isArray(raw.log)||!Number.isFinite(raw.dispatchClock)||raw.dispatchClock<0||!Number.isFinite(raw.transportFuelUsed)||raw.transportFuelUsed<0)throw Error('Повреждённая сеть бункеров');let ids=new Set(),people=new Set();for(let b of raw.bunkers){if(!Number.isInteger(b.id)||ids.has(b.id)||!Number.isInteger(b.gx)||!Number.isInteger(b.gy)||typeof b.founded!=='boolean'||typeof b.automatic!=='boolean')throw Error('Повреждённый бункер');ids.add(b.id);b.world=restore(serialize(b.world));if(b.world.bunkerBounds?.w!==30||b.world.bunkerBounds?.h!==20||!cell(b.world,b.world.hub?.x,b.world.hub?.y)||b.world.hub.x<0||b.world.hub.x>=30||b.world.hub.y<0||b.world.hub.y>=20)throw Error('Повреждённые границы');for(let p of b.world.people){if(people.has(p.id))throw Error('Дублированный житель');people.add(p.id);}}if(!ids.has(raw.active))throw Error('Неизвестный выбранный бункер');for(let l of raw.links)if(!ids.has(l.a)||!ids.has(l.b)||l.a===l.b||!Number.isFinite(l.travel)||l.travel<=0||![l.ea,l.eb].every(e=>e&&Number.isInteger(e.x)&&Number.isInteger(e.y)&&e.x>=0&&e.x<30&&e.y>=0&&e.y<20))throw Error('Повреждённый тоннель');for(let p of raw.projects)if(!ids.has(p.from)||!Array.isArray(p.crew)||!Number.isFinite(p.progress)||p.progress<0||p.progress>p.total||![80,160].includes(p.total))throw Error('Повреждённая стройка тоннеля');for(let t of raw.shipments){if(!ids.has(t.from)||!ids.has(t.to)||!Number.isFinite(t.remaining)||t.remaining<0||!Number.isFinite(t.total)||t.total<=0||!t.cargo||Object.entries(t.cargo).some(([k,v])=>!keys.includes(k)||!Number.isFinite(v)||v<0))throw Error('Повреждённый груз');for(let p of t.crew||[]){if(people.has(p.id))throw Error('Дублированный переселенец');people.add(p.id);}}return raw;}
export function bunkerStatus(b){let s=b.world,rooms=s.cells.filter(n=>n.x<30&&n.y<20),live=s.people.filter(p=>p.health>0),known=rooms.filter(n=>n.seen||n.type==='open').length,reasons=[];if(!b.founded)return {known,total:600,ready:false,reasons:['Поселение ещё не основано'],state:'Сектор'};if(known<600)reasons.push('Разведка '+known+'/600');if(!s.unlocks.includes('automation'))reasons.push('Нужна автоматизация');if(housingCapacity(s)<live.length)reasons.push('Недостаточно жилья');for(let type of ['generator','water','farm'])if(!rooms.some(n=>n.building===type&&n.enabled!==false&&(roomReport(s,n).utilization>0||s.resources[type==='farm'?'food':type==='water'?'water':'energy']>=capacity(s)-1)))reasons.push('Не работает '+BUILD[type].name);for(let k of ['food','water','fuel','energy'])if(s.resources[k]<Math.max(10,live.length*(k==='food'?.02:k==='water'?.025/3:k==='energy'?.08:.02)*120))reasons.push('Недостаточен запас '+k);return {known,total:600,ready:reasons.length===0,reasons,state:b.automatic?(reasons.length?'Требует внимания':'Автономен'):'Под управлением'};}
export function setBunkerAutomatic(c,id,value){let b=c.bunkers.find(b=>b.id===id);if(!b)return 'Неизвестный бункер';if(value&&!bunkerStatus(b).ready)return 'Для автономности: '+bunkerStatus(b).reasons.join('; ');b.automatic=!!value;b.manualOverride=!value;if(value){b.world.builderReserve=1;for(let p of b.world.people)if(!p.campaignProject){p.priority='auto';p.reservedBuilder=false;}}log(c,b.name+(value?' переведён на автономное управление':' под ручным управлением'));return null;}
export function surveyBunker(c,id){let b=c.bunkers.find(b=>b.id===id);if(!b?.founded)return 'Сначала основать поселение';let s=b.world;if(bunkerStatus(b).known===600)return 'Бункер уже обследован';if(!s.unlocks.includes('deepSurvey')||!s.cells.some(n=>n.building==='lab'&&path(s,hub(s),n)!==null))return 'Нужны «Экспедиции в глубины» и доступная лаборатория';if(s.researchPoints<10)return 'Нужны 10 научных данных';s.researchPoints-=10;for(let n of s.cells)if(n.x<30&&n.y<20){n.seen=true;n.surveyed=true;}log(c,'Полное геологическое обследование: '+b.name);return null;}
const directions={east:[1,0],west:[-1,0],down:[0,1],up:[0,-1]};
export function tunnelEntrance(c,from,direction='east'){let b=c.bunkers.find(b=>b.id===from);if(!b||!directions[direction])return null;let s=b.world;return s.cells.filter(n=>n.type==='open'&&!n.tunnelTo&&(direction==='east'?n.x===29:direction==='west'?n.x===0:direction==='down'?n.y===19:n.y===0)&&path(s,hub(s),n)!==null).sort((a,b)=>Math.abs((direction==='east'||direction==='west'?a.y-9.5:a.x-14.5))-Math.abs((direction==='east'||direction==='west'?b.y-9.5:b.x-14.5)))[0]||null;}
export function nextTunnelEntrance(c,from){let b=c.bunkers.find(b=>b.id===from);if(!b?.founded)return null;for(let direction of ['east','west','down','up']){let [dx,dy]=directions[direction];if(c.bunkers.some(n=>n.gx===b.gx+dx&&n.gy===b.gy+dy))continue;let edge=tunnelEntrance(c,from,direction);if(edge)return {direction,x:edge.x,y:edge.y};}return null;}
export function startTunnel(c,from,direction){let b=c.bunkers.find(b=>b.id===from),delta=directions[direction];if(!b?.founded||!delta)return 'Неверное направление';if(bunkerStatus(b).known<600)return 'Сначала исследуй все 600 участков текущего бункера';if(c.bunkers.some(n=>n!==b&&(!n.founded||bunkerStatus(n).known<600)))return 'Сначала заверши исследование уже открытого бункера';if(c.projects.length)return 'Сначала заверши текущий тоннель';let gx=b.gx+delta[0],gy=b.gy+delta[1];let existing=c.bunkers.find(n=>n.gx===gx&&n.gy===gy);if(existing&&c.links.some(l=>l.a===from&&l.b===existing.id||l.b===from&&l.a===existing.id))return 'Тоннель уже проложен';if(!existing&&c.bunkers.length>=12)return 'В этой версии доступно до 12 бункеров';let s=b.world,edge=tunnelEntrance(c,from,direction);if(!edge)return 'Раскопай проход до '+({east:'правого края',west:'левого края',down:'нижнего края',up:'верхнего края'})[direction]+' бункера';let crew=s.people.filter(p=>p.health>=70&&p.fatigue<=30&&!p.job&&!p.expedition&&!p.campaignProject&&p.task!=='Отдых'&&p.priority!=='operate'&&!s.cells.some(n=>n.preferredOperator===p.id)&&path(s,p,edge)!==null&&!['generator','water'].includes(cell(s,p.target?.x,p.target?.y)?.building)).slice(0,1);if(crew.length<1)return 'Нужен свободный здоровый строитель с энергией от 70%';let cost={material:40,metal:12,tools:2};if(Object.entries(cost).some(([k,v])=>freeStock(s,k)<v))return 'Для тоннеля нужны 40 материалов, 12 металла и 2 инструмента';for(let [k,v] of Object.entries(cost))s.resources[k]-=v;let id=c.nextId++,p={id,from,gx,gy,direction,targetId:existing?.id||null,edge:{x:edge.x,y:edge.y},crew:crew.map(p=>p.id),progress:0,total:80};c.projects.push(p);s.projectSites.push({id,x:edge.x,y:edge.y});for(let worker of crew){worker.campaignProject=id;worker.target=null;worker.path=[];}log(c,'Строится тоннель из '+b.name);return null;}
export const FOUND_COST={material:240,metal:90,food:120,water:150,fuel:100,tools:15};
export function foundBunker(c,to){let target=c.bunkers.find(b=>b.id===to);if(!target||target.founded||c.shipments.some(t=>t.kind==='found'&&t.to===to))return 'Поселение уже основано или группа в пути';let link=c.links.find(l=>l.a===to||l.b===to),from=link&&(link.a===to?link.b:link.a),b=c.bunkers.find(b=>b.id===from);if(!b?.founded)return 'Нужен тоннель из действующего бункера';let s=b.world,crew=s.people.filter(p=>p.health>=70&&p.fatigue<=30&&!p.job&&!p.expedition&&!p.campaignProject&&p.task!=='Отдых'&&p.priority!=='operate'&&!s.cells.some(n=>n.preferredOperator===p.id)&&!['generator','water'].includes(cell(s,p.target?.x,p.target?.y)?.building)).slice(0,5);if(crew.length<5||s.people.filter(p=>p.health>0).length<10)return 'Нужны пять свободных переселенцев; в старом бункере останется минимум пять жителей';if(Object.entries(FOUND_COST).some(([k,v])=>freeStock(s,k)<v))return 'Нужен комплект: 240 материалов, 90 металла, 120 пищи, 150 воды, 100 топлива, 15 инструментов';for(let [k,v] of Object.entries(FOUND_COST))s.resources[k]-=v;s.people=s.people.filter(p=>!crew.includes(p));for(let p of crew){p.path=[];p.target=null;p.job=null;delete p.routeStart;}c.shipments.push({id:c.nextId++,kind:'found',from,to,cargo:{...FOUND_COST},crew,remaining:link.travel,total:link.travel});log(c,'Пять переселенцев с модулями отправлены в '+target.name);return null;}
function linkOpen(c,l){let a=c.bunkers.find(b=>b.id===l.a),b=c.bunkers.find(b=>b.id===l.b);return a&&b&&path(a.world,hub(a.world),cell(a.world,l.ea.x,l.ea.y))!==null&&path(b.world,hub(b.world),cell(b.world,l.eb.x,l.eb.y))!==null;}
function finishProject(c,p){let source=c.bunkers.find(b=>b.id===p.from),existing=p.targetId&&c.bunkers.find(b=>b.id===p.targetId),world=existing?.world||boundedWorld((c.seed+Math.imul(p.id,7919))>>>0);if(!existing){world.people=[];world.resources=blank();world.groundwaterMax=0;world.arrivals=0;world.time=c.time;world.unlocks=[...source.world.unlocks];world.tech=source.world.tech;world.researchPoints=0;for(let n of world.cells)if(n.x<30&&n.y<20){n.type='rock';n.building=null;n.seen=false;}}let delta=directions[p.direction],entry={x:delta[0]>0?0:delta[0]<0?29:p.edge.x,y:delta[1]>0?0:delta[1]<0?19:p.edge.y};let n=cell(world,entry.x,entry.y);n.type='open';n.seen=true;if(!n.building)n.building=delta[1]?'stairs':'corridor';if(!existing?.founded)world.hub={...entry};let target=existing||{id:c.nextId++,name:'Бункер '+(c.bunkers.length+1),gx:p.gx,gy:p.gy,founded:false,automatic:false,world};if(!existing)c.bunkers.push(target);c.links.push({id:c.nextId++,a:source.id,b:target.id,ea:p.edge,eb:entry,travel:60+Math.abs(p.edge.x-hub(source.world).x)*2+Math.abs(p.edge.y-hub(source.world).y)*2});cell(source.world,p.edge.x,p.edge.y).tunnelTo=target.id;n.tunnelTo=source.id;for(let worker of source.world.people)if(worker.campaignProject===p.id){delete worker.campaignProject;worker.target=null;worker.path=[];if(worker.task!=='Отдых')worker.task='Ожидание';}source.world.projectSites=source.world.projectSites.filter(x=>x.id!==p.id);c.projects=c.projects.filter(x=>x!==p);log(c,'Тоннель готов. Можно отправить модульный бункер и переселенцев.');}
function landFounding(c,t){let b=c.bunkers.find(b=>b.id===t.to),old=b.world,fresh=boundedWorld(old.seed);for(let n of fresh.cells)if(n.x<30&&n.y<20){let original=cell(old,n.x,n.y);if(original.feature&&n.type==='rock')Object.assign(n,clone(original));}fresh.unlocks=[...c.bunkers.find(b=>b.id===t.from).world.unlocks];fresh.tech=old.tech;fresh.researchPoints=0;fresh.arrivals=0;fresh.time=c.time;fresh.resources={...blank(),...t.cargo,groundwater:4000};fresh.groundwaterMax=4000;if(old.clearedForRefounding){for(let k of keys)fresh.resources[k]=(old.resources[k]||0)+(t.cargo[k]||0);fresh.groundwaterMax=old.groundwaterMax;fresh.clearedForRefounding=false;}fresh.people=t.crew;fresh.jobs=[];for(let p of fresh.people){p.x=18;p.y=7;p.target=null;p.path=[];p.task='Ожидание';p.priority='auto';p.reservedBuilder=false;}let link=c.links.find(l=>l.a===b.id||l.b===b.id),entry=link.a===b.id?link.ea:link.eb;let current=cell(fresh,entry.x,entry.y);current.type='open';current.seen=true;current.building='corridor';current.tunnelTo=link.a===b.id?link.b:link.a;let x=entry.x,y=entry.y;while(x!==18){cell(fresh,x,y).type='open';cell(fresh,x,y).seen=true;if(!cell(fresh,x,y).building)cell(fresh,x,y).building='corridor';x+=Math.sign(18-x);}while(y!==7){cell(fresh,x,y).type='open';cell(fresh,x,y).seen=true;cell(fresh,x,y).building='stairs';y+=Math.sign(7-y);}let structures=fresh.cells.filter(n=>n.x<30&&n.y<20&&n.building);fresh.resources.material-=structures.reduce((n,c)=>n+BUILD[c.building].cost,0);fresh.resources.metal-=structures.reduce((n,c)=>n+BUILD[c.building].metal,0);if(fresh.resources.material<0||fresh.resources.metal<0)throw Error('Комплект не покрывает строительство');b.world=fresh;b.founded=true;log(c,b.name+' основан: 5 жителей, модули собраны из доставленных материалов.');}
function deliver(c,t){let destination=c.bunkers.find(b=>b.id===t.to);if(t.kind==='found'){landFounding(c,t);c.shipments=c.shipments.filter(x=>x!==t);return;}let cap=capacity(destination.world);for(let [k,v] of Object.entries(t.cargo)){let amount=Math.min(v,Math.max(0,cap-destination.world.resources[k]));destination.world.resources[k]+=amount;t.cargo[k]-=amount;}if(Object.values(t.cargo).every(v=>v<1e-8))c.shipments=c.shipments.filter(x=>x!==t);}
function dispatch(c){for(let l of c.links){if(!linkOpen(c,l))continue;for(let [from,to] of [[l.a,l.b],[l.b,l.a]]){let a=c.bunkers.find(b=>b.id===from),b=c.bunkers.find(b=>b.id===to);if(!a.founded||!b.founded)continue;let s=a.world,d=b.world,live=d.people.filter(p=>p.health>0).length,sourceLive=s.people.filter(p=>p.health>0).length,cargo={};let targets={food:Math.max(40,live*.02*300),water:Math.max(40,live*.025/3*300),fuel:60,material:80,metal:20,tools:20};for(let [k,wanted] of Object.entries(targets)){let incoming=c.shipments.filter(t=>t.to===to).reduce((n,t)=>n+(t.cargo[k]||0),0),reserve=k==='food'?Math.max(80,sourceLive*.02*600):k==='water'?Math.max(80,sourceLive*.025/3*600):({fuel:120,material:100,metal:35,tools:30})[k];let amount=Math.min(20,Math.max(0,freeStock(s,k)-reserve),Math.max(0,wanted-d.resources[k]-incoming),Math.max(0,capacity(d)-d.resources[k]-incoming));if(amount>.01)cargo[k]=amount;}if(!Object.keys(cargo).length||freeStock(s,'fuel')-(cargo.fuel||0)<1)continue;for(let [k,v] of Object.entries(cargo))s.resources[k]-=v;s.resources.fuel-=1;c.transportFuelUsed+=1;c.shipments.push({id:c.nextId++,kind:'cargo',from,to,cargo,remaining:l.travel,total:l.travel});}}}
export function stepCampaign(c,dt){dt=Math.max(0,Math.min(2,dt));if(dt===0)return;c.time+=dt;for(let b of c.bunkers){if(b.founded)step(b.world,dt);else b.world.time=c.time;}for(let p of [...c.projects]){let s=c.bunkers.find(b=>b.id===p.from).world,crew=p.crew.map(id=>s.people.find(w=>w.id===id));if(crew.some(w=>!w||w.health<=0)){for(let w of crew)if(w)delete w.campaignProject;s.projectSites=s.projectSites.filter(x=>x.id!==p.id);c.projects=c.projects.filter(x=>x!==p);log(c,'Стройка тоннеля остановлена: потерян участник.');continue;}p.progress=Math.min(p.total,p.progress+crew.filter(w=>w.task==='Прокладка тоннеля'&&!w.path.length&&Math.round(w.x)===p.edge.x&&Math.round(w.y)===p.edge.y).reduce((n,w)=>n+w.skill*dt,0));if(p.progress>=p.total)finishProject(c,p);}for(let t of [...c.shipments]){let link=c.links.find(l=>l.a===t.from&&l.b===t.to||l.a===t.to&&l.b===t.from);if(!link||!linkOpen(c,link))continue;if(t.kind==='found')for(let p of t.crew){let food=Math.min(t.cargo.food,p.health>0?.02*dt:0),water=Math.min(t.cargo.water,p.health>0?.025/3*dt:0);t.cargo.food-=food;t.cargo.water-=water;p.fatigue=Math.min(100,p.fatigue+.028*dt);}t.remaining=Math.max(0,t.remaining-dt);if(t.remaining===0)deliver(c,t);}c.dispatchClock+=dt;if(c.dispatchClock>=15){c.dispatchClock%=15;dispatch(c);}let knowledge=[...new Set(c.bunkers.flatMap(b=>b.world.unlocks))];for(let b of c.bunkers){b.world.unlocks=[...knowledge];if(!b.automatic&&!b.manualOverride&&bunkerStatus(b).ready)setBunkerAutomatic(c,b.id,true);if(b.automatic){let state=bunkerStatus(b).state;if(b.lastAutoState!==state&&state==='Требует внимания')log(c,b.name+': '+bunkerStatus(b).reasons.join('; '));b.lastAutoState=state;}}}
export function ensureUniqueResidentIds(c){let used=new Set();for(let b of c.bunkers)for(let p of b.world.people){if(used.has(p.id))p.id=Math.max(-1,...used)+1;used.add(p.id);}for(let t of c.shipments)for(let p of t.crew||[]){if(used.has(p.id))p.id=Math.max(-1,...used)+1;used.add(p.id);}}

export function recruitCampaign(c){let world=activeBunker(c).world,before=new Set(world.people),next=Math.max(-1,...c.bunkers.flatMap(b=>b.world.people.map(p=>p.id)),...c.shipments.flatMap(t=>(t.crew||[]).map(p=>p.id)))+1,error=recruit(world);if(error)return error;let offset=0;for(let p of world.people)if(!before.has(p))p.id=next+offset++;return null;}
export function shipmentStatus(c,t){let link=c.links.find(l=>l.a===t.from&&l.b===t.to||l.a===t.to&&l.b===t.from);return !link||!linkOpen(c,link)?'Рейс приостановлен: проход перекрыт':t.remaining===0?'Ожидает места на складе':'В пути';}

// Owner-requested one-time cleanup of the named second settlement, not numeric ID 2.
export function clearRequestedBunker2(c){if(c.bunker2CleanupV15)return false;c.bunker2CleanupV15=true;let b=c.bunkers.find(b=>b.name==='Бункер 2');if(!b)return false;let s=b.world,destination=c.bunkers.find(n=>n!==b&&n.founded);if(destination){for(let p of s.people){p.x=destination.world.hub.x;p.y=destination.world.hub.y;p.path=[];p.target=null;p.job=null;p.task='Ожидание';delete p.campaignProject;destination.world.people.push(p);}s.people=[];}
for(let n of s.cells){if(n.building&&!['stairs','corridor'].includes(n.building)){let refund=salvage(n.building);s.resources.material+=refund.material;s.resources.metal+=refund.metal;n.building=null;}delete n.preferredOperator;delete n.supply;delete n.delivery;delete n.productionTarget;delete n.enabled;}for(let j of s.jobs)for(let [k,v] of Object.entries(j.paid||{}))s.resources[k]+=v;s.jobs=[];s.projectSites=[];c.projects=c.projects.filter(p=>p.from!==b.id);b.automatic=false;b.manualOverride=true;s.metrics=null;log(c,'Бункер 2 очищен: помещения свободны, проходы и залежи сохранены. Жители переведены в первый бункер.');return true;}

export function clearRequestedBunkers234(c){if(c.bunkers234CleanupV17)return false;c.bunkers234CleanupV17=true;c.bunker2CleanupV15=true;let targets=c.bunkers.filter(b=>['Бункер 2','Бункер 3','Бункер 4'].includes(b.name));if(!targets.length)return false;let targetIds=new Set(targets.map(b=>b.id)),home=c.bunkers.find(b=>!targetIds.has(b.id)&&b.founded);if(!home)throw Error('Нет первого бункера для переселения');const move=p=>{p.x=home.world.hub.x;p.y=home.world.hub.y;p.target=null;p.path=[];p.job=null;p.task='Ожидание';delete p.campaignProject;delete p.expedition;home.world.people.push(p);};
for(let t of [...c.shipments])if(t.kind==='found'&&targetIds.has(t.to)){let source=c.bunkers.find(b=>b.id===t.from);for(let [k,v] of Object.entries(t.cargo))source.world.resources[k]+=v;for(let p of t.crew||[])move(p);c.shipments=c.shipments.filter(x=>x!==t);}
for(let b of targets){let s=b.world;for(let p of s.people)move(p);s.people=[];for(let n of s.cells){if(n.building&&!['stairs','corridor'].includes(n.building)){let refund=salvage(n.building);s.resources.material+=refund.material;s.resources.metal+=refund.metal;n.building=null;}delete n.preferredOperator;delete n.supply;delete n.delivery;delete n.productionTarget;delete n.enabled;}for(let j of s.jobs)for(let [k,v] of Object.entries(j.paid||{}))s.resources[k]+=v;s.jobs=[];for(let p of c.projects.filter(p=>p.from===b.id)){s.resources.material+=40;s.resources.metal+=12;s.resources.tools+=2;}c.projects=c.projects.filter(p=>p.from!==b.id);s.projectSites=[];s.expeditions=[];s.clearedForRefounding=true;b.founded=false;b.automatic=false;b.manualOverride=true;s.metrics=null;log(c,b.name+' очищен: можно заново отправить переселенцев. Проходы, геология и запасы сохранены.');}home.world.metrics=null;return true;}

// Explicit user-requested reset. Called only after an IndexedDB backup commits.
export function resetUnexploredBunkers(c){if(c.unexploredResetV18)return false;let targets=c.bunkers.filter(b=>['Бункер 2','Бункер 3','Бункер 4'].includes(b.name)),ids=new Set(targets.map(b=>b.id)),home=c.bunkers.find(b=>!ids.has(b.id)&&b.founded);if(targets.length&&!home)throw Error('Нет первого бункера для переселения');c.unexploredResetV18=true;c.bunkers234CleanupV17=true;c.bunker2CleanupV15=true;if(!targets.length)return false;const move=p=>{p.x=home.world.hub.x;p.y=home.world.hub.y;p.path=[];p.target=null;p.job=null;p.task='Ожидание';delete p.campaignProject;delete p.expedition;delete p.routeStart;home.world.people.push(p);};for(let b of targets){for(let p of b.world.people)move(p);for(let [k,v] of Object.entries(b.world.resources))if(!['energy','groundwater'].includes(k))home.world.resources[k]+=v;}
for(let t of c.shipments)if(ids.has(t.from)||ids.has(t.to)){for(let p of t.crew||[])move(p);for(let [k,v] of Object.entries(t.cargo))home.world.resources[k]+=v;}c.shipments=c.shipments.filter(t=>!ids.has(t.from)&&!ids.has(t.to));
for(let project of c.projects)if(ids.has(project.from)||ids.has(project.targetId)){let source=c.bunkers.find(b=>b.id===project.from),s=ids.has(project.from)?home.world:source.world;s.resources.material+=40;s.resources.metal+=12;s.resources.tools+=2;for(let b of c.bunkers){b.world.projectSites=b.world.projectSites.filter(n=>n.id!==project.id);for(let p of b.world.people)if(p.campaignProject===project.id){delete p.campaignProject;p.path=[];p.target=null;}}}c.projects=c.projects.filter(p=>!ids.has(p.from)&&!ids.has(p.targetId));c.links=c.links.filter(l=>!ids.has(l.a)&&!ids.has(l.b));c.bunkers=c.bunkers.filter(b=>!ids.has(b.id));for(let b of c.bunkers){for(let n of b.world.cells)if(ids.has(n.tunnelTo))delete n.tunnelTo;b.world.metrics=null;}if(ids.has(c.active))c.active=home.id;log(c,'Бункеры 2–4 удалены вместе с постройками, проходами и залежами. Новые сектора откроются после исследования и строительства тоннеля.');return true;}
